class Solution {
public:
    int countSpecialSubsequences(vector<int>& nums) {
        const long long M = 1000000007LL;
        long long a = 0, b = 0, c = 0;
        for (int x : nums) {
            if (x == 0) {
                a = (2LL * a + 1LL) % M;
            } else if (x == 1) {
                b = (2LL * b + a) % M;
            } else {
                c = (2LL * c + b) % M;
            }
        }
        return (int)c;
    }
};
